      else {
        $addr .= $_[0];
      }

      $addr =~ /0x(\\w+)/;
      local $^W;
      hex $1;
    }

(Excuse the nitpickery; sweating the details to this extent is
routine for me.)

Regards,
-- 
Aristotle Pagaltzis //

