         if eval { require Test::NoWarnings ;  import Test::NoWarnings; 1 
};

+if (ord("A") == 193) {
+    plan tests => 635 + $extra;
+}
+else {
     plan tests => 625 + $extra;
+}

 };


ext/IO_Compress_Zlib/t/101truncate-zip.t
--- 
/home/spring/perl/perl-current/ext/IO_Compress_Zlib/t/101truncate-zip.t 
2007-04-24 11:19:59.000000000 +0800
+++ /home/spring/patch/chgfile/ext-IO_Compress_Zlib-t-101truncate-zip.t 
2007-09-11 11:07:32.000000000 +0800
@@ -18,7 +18,12 @@
     $extra = 1
         if eval { require Test::NoWarnings ;  import Test::NoWarnings; 1 
};

+if (ord("A") == 193) {
+    plan tests => 2326 + $extra;
+}
+else {
     plan tests => 2316 + $extra;
+}

 };


Ge, Chun Bing
