body:
# New Ticket Created by  Alexandre Gorobets 
# Please include the string:  [perl #47305]
# in the subject line of all future correspondence about this issue. 
# 


This is a bug report for perl from xjqruiieb.xmsgkcgx@gmail.com,
generated with the help of perlbug 1.35 running under perl v5.8.4.

-----------------------------------------------------------------
[Please enter your report here]

use strict;
use warnings;

my %Instances;

package ZombyTest;

sub new {
    my $class = shift;
    my $name  = shift;

    $Instances{ $name }++;

    return bless \\$name;
}

sub DESTROY {
    my $self = shift;

    $Instances{ $$self }--;
};

# Test 1 - it's OK - silly check ;)
{
    my $test_1 = new ZombyTest( 'test_1' );
};

warn "test_1 is ", $Instances{'test_1'} ? 'zomby' : 'died';

# Test 2 - it's OK
{
    my $test_2 = new ZombyTest( 'test_2' );

    my $sub1 = sub {
        print $test_2;
    };
};

warn "test_2 is ", $Instances{'test_2'} ? 'zomby' : 'died';

# Test 3 - it's OK too ... why not ;)
{
    my $test_3 = new ZombyTest( 'test_3' );

    my $sub_1 = sub {
        print $test_3;
        my $sub_2 = sub {};
    };
};

warn "test_3 is ", $Instances{'test_3'} ? 'zomby' : 'died';

# Test 4 - first FAIL
# $test_4 - is zomby
{
    my $test_4 = new ZombyTest( 'test_4' );

    my $sub_1 = sub {
        my $sub_2 = sub {
            print $test_4;
        };
    };
};

warn "test_4 is ", $Instances{'test_4'} ? 'zomby' : 'died';

# Test 5 - another mysterious FAIL
# $test_5_2 - is zomby
# $test_5_1 - is zomby too ( only under v5.6.*)
{
    my $test_5_1 = new ZombyTest( 'test_5_1' );
    my $test_5_2 = new ZombyTest( 'test_5_2' );

    my $sub_1 = sub {
        print $test_5_1;
        my $sub_2 = sub {
            print $test_5_2;
        };
    };
};

warn "test_5_1 is ", $Instances{'test_5_1'} ? 'zomby' : 'died';
warn "test_5_2 is ", $Instances{'test_5_2'} ? 'zomby' : 'died';


P.S. I have also check this bug under v5.6.1 & v5.8.8


[Please do not change anything below this line]
